document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("theme-toggle-btn"),e=document.documentElement;(localStorage.getItem("theme")||"light")==="dark"?e.classList.add("dark"):e.classList.remove("dark"),t?.addEventListener("click",()=>{e.classList.toggle("dark");const l=e.classList.contains("dark")?"dark":"light";localStorage.setItem("theme",l)});const n=document.getElementById("mobile-menu-btn"),d=document.getElementById("mobile-menu-panel");n?.addEventListener("click",()=>{d?.classList.toggle("hidden")})});
